      const start = pos;
      while (pos < end && !isSep(lineStr.charCodeAt(pos))) pos++;
      let fieldEnd = pos;
      while (pos < end && isWhite(lineStr.charCodeAt(pos))) pos++;
      if (pos < end && isSep(lineStr.charCodeAt(pos))) pos++;
